import { Box, Tag } from "@chakra-ui/react";
import { Tooltip } from "../../Tooltip";
import { conditionMemorySummary } from "./conditionPhrase";

/** Memory map keyed by entry name, for condition tooltips. */
export type ConditionMemory = Record<string, { value: unknown }> | null | undefined;

/** Tag with the memory values of *condition*'s entries on hover. */
export function ConditionTag({
  label,
  condition,
  memory,
}: {
  readonly label: string;
  readonly condition: string;
  readonly memory: ConditionMemory;
}) {
  const summary = conditionMemorySummary(condition, memory);
  return (
    <Tooltip content={<Box whiteSpace="pre-line">{summary}</Box>} disabled={summary === null}>
      <Tag.Root variant="surface" size="sm" data-testid="skill-condition-entry">
        <Tag.Label>{label}</Tag.Label>
      </Tag.Root>
    </Tooltip>
  );
}
